import{_ as o,o as t,c as a,ag as i}from"./chunks/framework.qXLDknWC.js";const g=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),n={name:"changelog.md"};function l(r,e,c,d,s,h){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><h2 id="recent-changes" tabindex="-1">Recent Changes <a class="header-anchor" href="#recent-changes" aria-label="Permalink to &quot;Recent Changes&quot;">​</a></h2><h3 id="current-release-notes" tabindex="-1">Current Release Notes <a class="header-anchor" href="#current-release-notes" aria-label="Permalink to &quot;Current Release Notes&quot;">​</a></h3><ul><li><strong>NanoGPT PKCE sign-in</strong> — Sign in to NanoGPT directly from Settings → AI Config with a new <strong>Sign in with NanoGPT</strong> button. The OAuth flow uses PKCE (no client secret, no password leaves NanoGPT), and your available models are automatically fetched and loaded into the model picker as soon as sign-in completes. Popup blockers must be allowed. Works on Chrome for Android; other mobile browsers may not relay the auth code back — paste an API key manually if sign-in doesn&#39;t complete on your phone.</li><li>Added a <strong>Sections</strong> tab in Settings — hide, reorder, and reset your section tabs to match your workflow.</li><li>Improved the AI Settings tabs so they are easier to read and no longer overlap.</li><li>Reduced unwanted browser password prompts when entering AI settings.</li><li>Improved the character history view for screen readers.</li><li>Added simple editing for character names and creator names.</li><li>Added a cleaner tag editor where you can add, paste, and remove tags quickly.</li><li>Improved tag choices in AI Creation Studio so related tags work together more reliably.</li></ul><h3 id="latest-commits-newest-to-oldest" tabindex="-1">Latest Commits (Newest to Oldest) <a class="header-anchor" href="#latest-commits-newest-to-oldest" aria-label="Permalink to &quot;Latest Commits (Newest to Oldest)&quot;">​</a></h3><ul><li><code>00c188d</code> - feat(auth): auto-fetch models after NanoGPT OAuth sign-in</li><li><code>f019115</code> - style(ui): update NanoGPT sign-in success toast message</li><li><code>55c0ec7</code> - feat(auth): add NanoGPT OAuth sign-in flow</li><li><code>974ff11</code> - refactor(ai): enhance copy button timeout handling and variable scoping</li><li><code>461ace4</code> - feat(mobile): enable copy button visibility on mobile devices</li><li><code>43bb8ce</code> - feat(ui): add stats tooltip and mobile copy button visibility</li><li><code>4379702</code> - feat(ai): implement response performance metrics</li><li><code>2789636</code> - feat(character): adjust sampler parameter ranges</li><li><code>8952b08</code> - perf(character): optimize model caching and provider selection</li><li><code>456ded4</code> - feat(eslint): add &#39;docs&#39; to global ignores in ESLint configuration</li><li><code>a33ff1d</code> - feat(character): add caching for AI models in settings panel</li><li><code>52de543</code> - feat(character): implement imported character flag for conditional snapshot creation</li><li><code>cce7d44</code> - feat(ui): add create new button and improve create form layout for mobile</li><li><code>281be66</code> - fix(editor): integrate toolbar search with CodeMirror panel lifecycle to stop selection scroll oscillation</li><li><code>324ce81</code> - feat(editor): enhance search navigation with auto-scroll and panel positioning</li><li><code>9a014e0</code> - fix(ai): resolve context at call time to prevent stale system prompt</li><li><code>1992244</code> - feat(editor): add custom tab handling and indentation settings in useAIEditor</li><li><code>9722bba</code> - feat(editor): add lorebook import and export functionality</li><li><code>640e573</code> - refactor(lorebook): filter out empty character books during export</li><li><code>9d0d662</code> - refactor(history): prevent content flash during modal entrance with delayed visibility</li><li><code>d4f9696</code> - feat(components): enhance input handling and loading animations</li><li><code>9fc0bd7</code> - refactor(db): implement content-addressed storage for character images</li><li><code>aa4cc58</code> - feat(ai): enable multi-line input in AI chat and toolbar panels</li><li><code>24a629d</code> - refactor(lorebook): swap name and comment fields in entry editor to match SillyTavern convention</li><li><code>f4618c6</code> - refactor(lorebook): extract case_sensitive extension handling to variable</li><li><code>7851a6f</code> - fix(lorebook): Lorebook Export/Import Compatibility Fix</li></ul>',6)])])}const f=o(n,[["render",l]]);export{g as __pageData,f as default};
